import{z as A,x as l,o as n,c as d,q as r,j as t,D as e,d as B,s as i,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"连接池","description":"","frontmatter":{"title":"连接池","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/connection-pooling.md","filePath":"cs/connection-pooling.md","lastUpdated":1791063341000}'),p={name:"cs/connection-pooling.md"};function c(C,E,D,m,h,T){const o=l("Mermaid");return n(),d("div",null,[E[2]||(E[2]=r('<h1 id="连接池" tabindex="-1">连接池 <a class="header-anchor" href="#连接池" aria-label="Permalink to &quot;连接池&quot;">​</a></h1><div class="epigraph"><p>会话在库内是内存、锁与临时状态的所有者；池把建立会话的代价摊到多次请求，但把隔离与事务边界从「连接寿命」里拆出来。</p><footer>—— 据 Gray and Reuter 对会话；HikariCP / 数据库手册对池化实践；Ramakrishnan and Gehrke</footer></div><p><a href="/cs/orm-impedance">上一课</a>指出对象导航会打出许多语句。本课不修 N+1。缺口是每条语句下面的<strong>会话</strong>：TCP、认证、后端进程或线程、会话级设置。<span class="marginnote">「会话」翻译成白话：从登录数据库到断开之间的整段「对话」——服务端为它一直记着变量、临时表和锁。池借走的不是一个空洞的套接字，而是这段记忆的保管权，所以还回去前必须把记忆擦干净。</span>每次请求新建连接，延迟与进程数都会打爆。连接池在应用侧（或中间件）保持一组就绪会话，借出还回。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>库的并发容量常按连接数计：每个后端有缓冲区、准备语句缓存、可能还有锁。连接数 ≈ 峰值并发请求会让上下文切换与内存爆炸。缺口是复用：池大小、超时、失效检测（后端已死但套接字还在）。事务必须在还池前结束：把打开事务的连接还回去，下一个请求会看见未提交状态或锁——这是正确性 bug，不是性能调参。</p><p>会话级状态：<code>SET</code>、临时表、顾问锁、未用完的游标。还池必须重置，否则请求之间泄漏。这与 <a href="/cs/savepoints">保存点</a> 不同：保存点属于事务，池属于会话寿命。</p><p><span class="marginnote">服务器侧也有池（PgBouncer 一类）把许多客户端复用到较少后端。事务模式与会话模式决定临时表能否跨请求。本课把「会话有状态」钉死，模式选择是产品合同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>应用池：固定上限、队列或拒绝、空闲逐出、连接校验查询。借出范围 = 一次请求或一次工作单元，与 ORM 会话对齐。只读副本：另一池，避免写事务发到备库却假定可写。</p><p>池不能增加库的逻辑并发上限，只减少建立代价并平滑峰值。库侧 <code>max_connections</code> 仍是硬顶。<span class="marginnote">初学者容易以为「池开得越大越快」，实际上数据库的并发上限不随连接数变大：几百个连接只会让后端互相争抢 CPU 与锁表，吞吐反而下滑。池是把峰值削平的蓄水池，不是加大水厂的阀门。</span></p>',10)),(n(),t(s,null,{default:e(()=>[i(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20BORROW%5B%22%E4%BB%8E%E6%B1%A0%E5%80%9F%E4%BC%9A%E8%AF%9D%22%5D%0A%20%20BORROW%20--%3E%20TX%5B%22%E5%BC%80%E4%BA%8B%E5%8A%A1%E5%81%9A%E5%AE%8C%22%5D%0A%20%20TX%20--%3E%20END%5B%22%E6%8F%90%E4%BA%A4%E6%88%96%E5%9B%9E%E6%BB%9A%22%5D%0A%20%20END%20--%3E%20RESET%5B%22%E9%87%8D%E7%BD%AE%E4%BC%9A%E8%AF%9D%E7%8A%B6%E6%80%81%22%5D%0A%20%20RESET%20--%3E%20RET%5B%22%E8%BF%98%E6%B1%A0%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[B("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"预编译语句与会话绑定：有的引擎把计划缓在后端。池稳定后，同一后端反复看到相似语句，后课计划缓存才有命中。连接抖动（频繁新建）则缓存冷。SSL 握手摊销也是池的理由。",-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"给个数字实例：新建一条连接 = TCP 三次握手约 1 个 RTT + TLS 握手 1–2 个 RTT + 认证一轮，局域网也要几毫秒，跨地域可达几十毫秒；池化后这笔钱只在预热时付一次。池大小常按「核数 × 2 + 磁盘数」的量级起步，而不是越大越好。")],-1)),(n(),t(s,null,{default:e(()=>[i(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEED%5B%22%E8%AF%B7%E6%B1%82%E6%9D%A5%E8%A6%81%E8%BF%9E%E6%8E%A5%22%5D%20--%3E%20IDLE%7B%22%E6%B1%A0%E9%87%8C%E6%9C%89%E7%A9%BA%E9%97%B2%E8%BF%9E%E6%8E%A5%EF%BC%9F%22%7D%0A%20%20IDLE%20--%3E%7C%22%E6%9C%89%22%7C%20CHK%5B%22%E5%80%9F%E5%87%BA%E5%89%8D%E5%8F%91%E6%A0%A1%E9%AA%8C%E6%9F%A5%E8%AF%A2%22%5D%0A%20%20CHK%20--%3E%7C%22%E5%93%8D%E5%BA%94%E6%AD%A3%E5%B8%B8%22%7C%20USE%5B%22%E4%BA%A4%E4%BB%98%E8%AF%B7%E6%B1%82%E4%BD%BF%E7%94%A8%22%5D%0A%20%20CHK%20--%3E%7C%22%E8%B6%85%E6%97%B6%E6%88%96%E6%8A%A5%E9%94%99%22%7C%20KILL%5B%22%E4%B8%A2%E5%BC%83%E6%AD%BB%E8%BF%9E%E6%8E%A5%E5%86%8D%E6%89%BE%22%5D%0A%20%20KILL%20--%3E%20IDLE%0A%20%20IDLE%20--%3E%7C%22%E6%B2%A1%E6%9C%89%E4%B8%94%E6%9C%AA%E5%88%B0%E4%B8%8A%E9%99%90%22%7C%20NEW%5B%22%E6%96%B0%E5%BB%BA%EF%BC%9A%E4%BB%98%20TCP%20%2B%20TLS%20%2B%20%E8%AE%A4%E8%AF%81%22%5D%0A%20%20IDLE%20--%3E%7C%22%E6%B2%A1%E6%9C%89%E4%B8%94%E5%B7%B2%E5%88%B0%E4%B8%8A%E9%99%90%22%7C%20QUEUE%5B%22%E6%8E%92%E9%98%9F%E7%AD%89%E5%BE%85%EF%BC%8C%E8%B6%85%E6%97%B6%E5%88%99%E6%8B%92%E7%BB%9D%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p>线程与连接：一请求一连接简单；异步运行时可能更少连接多路复用协议（若库支持）。本课不把异步驱动当默认模型。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲计划缓存的失效与绑定窥视——下一课。也不把池当限流器的全部：队列过长等于把延迟藏在应用里。分布式事务里每个资源管理器仍要会话，池按库实例分。</p><p>后课默认：连接是稀缺会话，事务在还池前关闭，会话状态不泄漏。预编译与计划缓存建立在「同一后端反复出现同一语句形状」上。</p><p>池解决的是会话造价，不解决慢查询、不解决阻抗失配。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>池复用会话，上限对齐库容量；还池前必须结束事务并重置状态。</li><li>服务器侧池化改变临时表与会话语义，要按模式读合同。</li><li>预编译与计划缓存下一课：形状稳定之后，计划才能留住。</li><li>出处：Gray and Reuter；Ramakrishnan and Gehrke；池化中间件实践。</li></ul>',7))])}const f=A(p,[["render",c]]);export{_ as __pageData,f as default};
